function streamBody(reader, test, count = 0) {
  return reader.read().then(function(data) {
    if (!data.done && count < 2) {
      count += 1;
      return streamBody(reader, test, count);
    } else {
      test.step(function() {
        assert_true(count >= 2, "Retrieve body progressively");
      });
    }
  });
}

