  return fetch(url + delay, { keepalive: true, body, method: 'POST' }).then(res => {
      return res.text();
  }).then(() => {
      return new Promise(resolve => step_timeout(resolve, 1));
  }).catch((error) => {
      return Promise.reject(error);;
  })
