 */
function make_absolute_url(options) {
    function get(obj, name, default_val) {
        if (obj.hasOwnProperty(name)) {
            return obj[name];
        }
        return default_val;
    }

    var loc = window.location;
    var protocol = get(options, "protocol", loc.protocol);
    if (protocol[protocol.length - 1] != ":") {
